function toast(msg){const e=document.querySelector('#toast');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2400)}
function drawer(title,html){document.querySelector('#drawerBody').innerHTML=`<span class="eyebrow">Details</span><h2>${title}</h2>${html}`;const d=document.querySelector('#drawer');d.classList.add('open');d.setAttribute('aria-hidden','false');bind()}
function modal(title,html){document.querySelector('#modalBody').innerHTML=`<span class="eyebrow">TMZ morning brief</span><h2>${title}</h2>${html}`;document.querySelector('#modal').classList.remove('hidden')}
function actionRow(icon,title,meta,label,cls=''){return `<div class="action-row"><div class="action-icon">${icon}</div><div class="action-copy"><b>${title}</b><small>${meta}</small></div><button class="btn ${cls}" data-toast="${label}: ${title}">${label}</button></div>`}
function trainingCard(){if(location.hash==='#content')return '';return `<section class="training card"><div class="training-ring">5:00</div><div><span class="eyebrow">Daily training</span><h2>Teach the system how you think</h2><p>Today: What makes a student startup genuinely worth featuring?</p></div><button class="btn orange" data-training>Start five-minute training</button></section>`}
function momentum(){return `<section class="card"><div class="card-head momentum-head"><div><span class="eyebrow">Brand momentum</span><h2>Every channel, one view</h2></div><div class="control-row"><select id="kpiSelect">${Object.keys(kpis).map(k=>`<option>${k}</option>`).join('')}</select><div class="tabs period-tabs"><button>Today</button><button class="active">30 days</button><button>90 days</button></div></div></div><div class="momentum" id="momentumGrid"></div></section>`}
function renderMomentum(metric='New followers'){const el=document.querySelector('#momentumGrid');if(!el)return;el.innerHTML=kpis[metric].map(c=>`<button class="metric metric-button" data-toast="Opening ${c[0]} ${metric.toLowerCase()} details"><span class="platform">${c[0]}</span><strong>${c[1]}</strong><span class="up">↑ ${c[2]}</span><div class="mini-bars">${[34,51,42,63,58,85,76].map(h=>`<i style="height:${h}%"></i>`).join('')}</div><small>Tip: ${c[0]==='LinkedIn'?'Lead with a strong opinion':c[0]==='YouTube'?'Use searchable founder questions':c[0]==='TikTok'?'Cut the setup by two seconds':'Ask viewers to save the framework'}</small></button>`).join('')}
function needsStrip(){return `<section class="compact-needs"><div class="compact-title"><span class="eyebrow">Ranked by impact + timing</span><h2>What needs you now</h2></div><div class="need-list">${priorities.map((p,i)=>`<button class="need-row" data-priority="${i}"><span class="rank">${i+1}</span><span><b>${p.title}</b><small>${p.meta}</small></span><em>${p.action} →</em></button>`).join('')}</div></section>`}
function radarCards(limit=stories.length){return `<div class="radar-cards">${stories.slice(0,limit).map((s,i)=>`<article class="radar-card" data-story="${i}"><img src="${s.image}" alt="Story preview"><div class="radar-overlay"><span class="score-mini">${s.score}</span><b>${s.title}</b><small>${s.source}</small><p>${s.why}</p><div><button class="btn orange" data-read="${i}">Open story</button><button class="btn glass" data-quick-record="${i}">Record now</button></div></div></article>`).join('')}</div>`}
function today(){return `${needsStrip()}<div class="top-actions"><section class="card"><div class="card-head"><div><span class="eyebrow">Strategy + opportunities</span><h2>Ready for action</h2></div><button class="text-btn" data-nav="partnerships">View all →</button></div><div class="quick-opps three"><button data-opportunity="0"><b>Media comment</b><small>AI operators + small business · Draft ready</small><em>2 min</em></button><button data-opportunity="1"><b>High-value collaboration</b><small>Established founder platform · Intro mapped</small><em>5 min</em></button><button data-idea><b>Double down on pricing stories</b><small>2.4× saves · 3-piece plan prepared</small><em>Review →</em></button></div></section>${trainingCard()}</div><div class="today-board"><section class="card"><div class="card-head"><div><span class="eyebrow">Automatic content engine</span><h2>One recording → four channels</h2></div><div class="tabs"><button class="active">Needs Bert · 2</button><button>In production · 5</button><button>Content Bank · 18</button></div></div>${actionRow('●','Best cities for Hispanic entrepreneurs','Record approved master · 8 min','Open details','orange')}${actionRow('✓','Founder ad-testing lesson','Review four automatic adaptations','Review')}${actionRow('↗','Why founders keep losing money on ads','Editing now · Publish priority recalculating','View')}</section><section class="card"><div class="card-head"><div><span class="eyebrow">On the radar</span><h2>Select, script, or record</h2></div><button class="text-btn" data-nav="radar">Full radar →</button></div>${radarCards(3)}</section></div><div class="dashboard-gap"></div>${momentum()}<div class="dashboard-gap"></div><div class="today-lower"><section class="card"><div class="card-head"><div><span class="eyebrow">Social inbox</span><h2>Replies needing approval</h2></div><span class="pill orange">1 sensitive</span></div>${actionRow('!','Critical comment detected','Draft withheld—manual review required','Review safely','orange')}${actionRow('↗','Founder asks about first customers','Suggested reply ready','Approve reply')}</section><section class="card"><div class="card-head"><div><span class="eyebrow">Grow the brand</span><h2>Ideas</h2></div><button class="btn light" data-free-record>● Talk through an idea</button></div><div class="idea-row" data-idea><b>Create a “Professor Office Hours” response format</b><small>High potential · Solo · No cost · 30 minutes to pilot</small></div><div class="idea-row" data-idea><b>Capture small-business observations in the field</b><small>Smart-glasses optional · Impromptu · National relevance</small></div></section></div>`}
function content(){return `<div class="page-head"><div><span class="eyebrow">Production command center</span><p>Record once. Review the details. The system adapts, banks, prioritizes, and publishes.</p></div><div class="head-buttons"><button class="btn light" data-free-record>● Just start talking</button><button class="btn orange" data-toast="Recording session opened">Start recording session</button></div></div>${trainingCard()}<div class="dashboard-gap"></div><section class="card"><div class="card-head"><div class="tabs"><button class="active">Needs Bert · 2</button><button>In production · 5</button><button>Content Bank · 18</button><button>Published · 64</button></div><span class="subtle">Next recording batch · 21 minutes</span></div><div class="content-table">${contentItems.map((x,i)=>`<button class="content-row" data-content="${i}"><span class="status-dot"></span><span><b>${x.title}</b><small>${x.detail}</small></span><span class="pill">${x.stage}</span><em>${x.action} →</em></button>`).join('')}</div></section><div class="dashboard-gap"></div><section class="card"><div class="card-head"><div><span class="eyebrow">Search everything</span><h2>Content Library</h2></div><div class="library-search"><input placeholder="Search videos, ideas, people, topics…"><button class="btn">Search</button></div></div><div class="tag-cloud">${['Student startups','Founder lessons','Tampa','Hispanic entrepreneurs','AI','Pricing','First customers','Classroom insight','Media comments'].map(t=>`<button>${t}</button>`).join('')}</div><div class="library-grid">${['Approved videos · 18','Raw recordings · 27','Content ideas · 41','Article assets · 36'].map(x=>`<button data-toast="Opening ${x}"><b>${x.split(' · ')[1]}</b><span>${x.split(' · ')[0]}</span></button>`).join('')}</div></section>`}
function radar(){return `<div class="page-head"><div><span class="eyebrow">Live opportunity feed</span><p>Outside stories stay here until you accept them. Accepted stories move into Content.</p></div><div class="date-chip">142 sources scanned · Updated 6 min ago</div></div><section class="card"><div class="card-head"><div><h2>Ranked for your brand</h2><span class="subtle">Freshness, audience fit, visual potential, credibility, and speed.</span></div><div class="tabs"><button class="active">All</button><button>Student startups</button><button>Expert comment</button><button>Fast-moving</button></div></div>${radarCards()}</section><div class="dashboard-gap"></div><section class="card"><div class="card-head"><h2>Radar actions</h2><span class="subtle">Nothing enters production until you approve it.</span></div><div class="quick-opps"><button data-toast="Expert statement opportunities filtered"><b>Offer expert comment</b><small>7 requests or stories match your expertise</small><em>Review →</em></button><button data-toast="Saved story list opened"><b>Saved for later</b><small>12 relevant, non-urgent stories</small><em>Open →</em></button></div></section>`}
function audience(){return `<div class="page-head"><div><span class="eyebrow">People, not vanity metrics</span><p>Audience intelligence that ends with a recommended action.</p></div><div class="date-chip">30-day audience growth · +15.2%</div></div><section class="card"><div class="card-head"><div><span class="eyebrow">Growth plan</span><h2>Recommended next moves</h2></div><span class="pill green">Updated today</span></div><div class="growth-actions">${[['Instagram','Publish a carousel companion to the strongest Reel.','Create brief'],['TikTok','Answer the first-customer question as a direct video reply.','Open reply'],['YouTube','Package three Shorts into one searchable series.','Build series'],['LinkedIn','Review Monday’s weekly professor post—image, copy, tags, and @mentions ready.','Review post']].map(x=>`<article><span>${x[0]}</span><b>${x[1]}</b><button class="btn light" data-toast="${x[2]} started">${x[2]}</button></article>`).join('')}</div></section><div class="dashboard-gap"></div>${momentum()}<div class="dashboard-gap"></div><div class="audience-grid"><section class="card"><div class="card-head"><div><span class="eyebrow">Who is here</span><h2>Audience composition</h2></div><div class="fresh-insight"><b>Fresh insight</b><span>Your audience now reaches 12 countries.</span></div></div><div class="demo-grid">${[['Role','Aspiring founders 34%','Student founders 27%'],['Age','25–34: 38%','35–44: 29%'],['Top states','FL · TX · NY · CA · GA','61% outside Florida'],['Experience','Pre-launch 31%','0–3 years 28%']].map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b><span>${x[2]}</span></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><span class="eyebrow">What they are telling you</span><h2>Questions + signals</h2></div><span class="pill">47 questions</span></div><div class="signal-row"><b>“How do I get my first ten customers?”</b><small>18 related comments across TikTok and Instagram</small><button class="btn light" data-toast="Series created; research and scripts are now being prepared">Build 3-part series</button></div><div class="signal-row"><b>Pricing breakdowns are outperforming.</b><small>2.4× saves among owners aged 25–44</small><button class="btn light" data-toast="Follow-ups created and queued for production">Create follow-ups</button></div></section></div>`}
